CREATE TABLE moviefinder."user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, username text UNIQUE, display_username text, bio text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moviefinder.session (id text PRIMARY KEY, expires_at timestamptz NOT NULL, token text NOT NULL UNIQUE, ip_address text, user_agent text, user_id text NOT NULL REFERENCES moviefinder."user"(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX session_user_idx ON moviefinder.session(user_id);
CREATE TABLE moviefinder.account (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES moviefinder."user"(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX account_user_idx ON moviefinder.account(user_id);
CREATE TABLE moviefinder.verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_identifier_idx ON moviefinder.verification(identifier);
CREATE TABLE moviefinder.source_entity (id text PRIMARY KEY, provider text NOT NULL DEFAULT 'tmdb', entity_type text NOT NULL, external_id text NOT NULL, payload jsonb NOT NULL, schema_version integer NOT NULL DEFAULT 1, projection text NOT NULL DEFAULT 'summary' CHECK(projection IN ('summary','detail')), checksum text NOT NULL, fetched_at timestamptz NOT NULL, refresh_at timestamptz NOT NULL, last_success timestamptz NOT NULL, last_failure timestamptz, error text, version bigint NOT NULL DEFAULT 1, title text NOT NULL, genres integer[] NOT NULL DEFAULT '{}', popularity real NOT NULL DEFAULT 0, rating real NOT NULL DEFAULT 0, release_date text);
CREATE UNIQUE INDEX source_identity_idx ON moviefinder.source_entity(provider,entity_type,external_id);
CREATE INDEX source_type_popularity_idx ON moviefinder.source_entity(entity_type,popularity);
CREATE INDEX source_type_rating_idx ON moviefinder.source_entity(entity_type,rating);
CREATE INDEX source_release_idx ON moviefinder.source_entity(release_date);
CREATE INDEX source_refresh_idx ON moviefinder.source_entity(refresh_at);
CREATE INDEX source_genres_idx ON moviefinder.source_entity USING gin(genres);
CREATE INDEX source_search_idx ON moviefinder.source_entity USING gin(to_tsvector('simple',title));
CREATE TABLE moviefinder.query_cache (id text PRIMARY KEY, name text NOT NULL, params jsonb NOT NULL, ids text[] NOT NULL DEFAULT '{}', complete boolean NOT NULL DEFAULT false, next_page integer, fetched_at timestamptz, refresh_at timestamptz, error text, version bigint NOT NULL DEFAULT 1);
CREATE TABLE moviefinder.sync_job (id text PRIMARY KEY, kind text NOT NULL, params jsonb NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','running','done','failed')), attempts integer NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sync_job_due_idx ON moviefinder.sync_job(state,run_at);
CREATE TABLE moviefinder.title_status (id text PRIMARY KEY, user_id text NOT NULL REFERENCES moviefinder."user"(id) ON DELETE CASCADE, title_id text NOT NULL REFERENCES moviefinder.source_entity(id), seen boolean NOT NULL DEFAULT false, sentiment text NOT NULL DEFAULT 'unrated' CHECK(sentiment IN ('liked','meh','disliked','unrated')), version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX status_user_title_idx ON moviefinder.title_status(user_id,title_id);
CREATE TABLE moviefinder.list (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES moviefinder."user"(id), title text NOT NULL, description text NOT NULL DEFAULT '', version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moviefinder.list_item (id text PRIMARY KEY, list_id text NOT NULL REFERENCES moviefinder.list(id) ON DELETE CASCADE, title_id text NOT NULL REFERENCES moviefinder.source_entity(id), order_key text COLLATE "C" NOT NULL, added_by text NOT NULL REFERENCES moviefinder."user"(id), version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX list_title_idx ON moviefinder.list_item(list_id,title_id);
CREATE INDEX list_order_idx ON moviefinder.list_item(list_id,order_key);
CREATE TABLE moviefinder.collaborator (id text PRIMARY KEY, list_id text NOT NULL REFERENCES moviefinder.list(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES moviefinder."user"(id), role text NOT NULL CHECK(role IN ('owner','editor')), version bigint NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX collaborator_list_user_idx ON moviefinder.collaborator(list_id,user_id);
CREATE TABLE moviefinder.invitation (id text PRIMARY KEY, list_id text NOT NULL REFERENCES moviefinder.list(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES moviefinder."user"(id), invited_by text NOT NULL REFERENCES moviefinder."user"(id), state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','declined')), version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX invitation_list_user_idx ON moviefinder.invitation(list_id,user_id);
CREATE TABLE moviefinder.follow (id text PRIMARY KEY, user_id text NOT NULL REFERENCES moviefinder."user"(id), target_id text NOT NULL, target_kind text NOT NULL CHECK(target_kind IN ('user','list')), version bigint NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX follow_user_target_idx ON moviefinder.follow(user_id,target_id,target_kind);
CREATE TABLE moviefinder.saved_feed (id text PRIMARY KEY, user_id text NOT NULL REFERENCES moviefinder."user"(id), title text NOT NULL, params jsonb NOT NULL, version bigint NOT NULL DEFAULT 1);
CREATE TABLE moviefinder.activity (id text PRIMARY KEY, user_id text NOT NULL REFERENCES moviefinder."user"(id), title text NOT NULL, target_id text NOT NULL, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moviefinder.event (id bigserial PRIMARY KEY, audience text, subscription text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX event_created_idx ON moviefinder.event(created_at);
CREATE TABLE moviefinder.operation (user_id text NOT NULL REFERENCES moviefinder."user"(id) ON DELETE CASCADE, id text NOT NULL, fingerprint text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,id));
